// Validate input parameters
const body = $input.first().json.body ?? $input.first().json;
const partner_id = body.partner_id;
const session_id = body.session_id;
const user_answers = body.answers ?? [];

if (!partner_id) {
  throw new Error('partner_id is required');
}

return [{ json: { partner_id, session_id, user_answers } }];

// Load existing design profile via MCP
const { partner_id } = $input.first().json;

const mcpUrl = $env.AISHA_POSTGREST_URL + '/functions/v1/mcp-knowledge-server';
const mcpToken = $env.AISHA_ACCESS_TOKEN;

const response = await fetch(mcpUrl, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${mcpToken}`
  },
  body: JSON.stringify({
    jsonrpc: '2.0',
    id: 1,
    method: 'tools/call',
    params: {
      name: 'get_design_profile',
      arguments: { partner_id }
    }
  })
});

const result = await response.json();
const profile = result?.result?.content?.[0]?.text ?? null;
const existingProfile = profile ? JSON.parse(profile) : null;

return [{ json: { ...$input.first().json, existing_profile: existingProfile } }];

// Load personality context from Hippocampus via compose_context
const { partner_id } = $input.first().json;

const mcpUrl = $env.AISHA_POSTGREST_URL + '/functions/v1/mcp-knowledge-server';
const mcpToken = $env.AISHA_ACCESS_TOKEN;

const response = await fetch(mcpUrl, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${mcpToken}`
  },
  body: JSON.stringify({
    jsonrpc: '2.0',
    id: 2,
    method: 'tools/call',
    params: {
      name: 'compose_context',
      arguments: {
        agent_slug: 'occipitum',
        context_profile_slug: 'chat_lightweight',
        query: 'design DNA interview personality context'
      }
    }
  })
});

const result = await response.json();
const context = result?.result?.content?.[0]?.text ?? '';

return [{ json: { ...$input.first().json, personality_context: context } }];

// Generate adaptive interview questions based on existing profile gaps
const { existing_profile, user_answers, personality_context } = $input.first().json;

const profile = existing_profile?.profile ?? null;
const hasProfile = existing_profile?.status === 'ok';

// Determine what's missing from the profile
const gaps = [];
if (!hasProfile || !profile?.brand_dna?.personality) gaps.push('brand_personality');
if (!hasProfile || !profile?.brand_dna?.tone_of_voice) gaps.push('tone_of_voice');
if (!hasProfile || !profile?.ux_persona?.goals?.length) gaps.push('user_goals');
if (!hasProfile || !profile?.ux_persona?.emotional_expectations?.length) gaps.push('emotional_expectations');
if (!hasProfile || !profile?.style_preferences?.liked_styles?.length) gaps.push('style_preferences');
if (!hasProfile || !profile?.style_preferences?.vibe_words?.length) gaps.push('vibe_words');
if (!hasProfile || !profile?.design_constraints?.accessibility_level) gaps.push('accessibility');

// How many answers do we have already?
const answeredCount = user_answers?.length ?? 0;
const maxQuestions = 8;
const remainingQuestions = Math.max(0, maxQuestions - answeredCount);

// If all gaps filled or max questions reached, we're done
const isComplete = gaps.length === 0 || remainingQuestions === 0;

return [{ json: {
  ...$input.first().json,
  gaps,
  is_complete: isComplete,
  remaining_questions: remainingQuestions,
  answered_count: answeredCount
} }];

// Extract design DNA from all collected answers
const { user_answers, existing_profile, partner_id } = $input.first().json;

// Build structured profile from LLM-extracted answers
// The LLM response contains extracted_dna JSON
const llmResponse = $input.first().json.llm_response;
let extractedDna;
try {
  extractedDna = typeof llmResponse === 'string' ? JSON.parse(llmResponse) : llmResponse;
} catch {
  extractedDna = { brand_dna: {}, ux_persona: {}, style_preferences: {} };
}

return [{ json: {
  partner_id,
  brand_dna: extractedDna.brand_dna ?? {},
  ux_persona: extractedDna.ux_persona ?? {},
  style_preferences: extractedDna.style_preferences ?? {},
  design_constraints: extractedDna.design_constraints ?? {}
} }];

// Upsert design profile via MCP
const { partner_id, brand_dna, ux_persona, style_preferences, design_constraints } = $input.first().json;

const mcpUrl = $env.AISHA_POSTGREST_URL + '/functions/v1/mcp-knowledge-server';
const mcpToken = $env.AISHA_ACCESS_TOKEN;

const response = await fetch(mcpUrl, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${mcpToken}`
  },
  body: JSON.stringify({
    jsonrpc: '2.0',
    id: 3,
    method: 'tools/call',
    params: {
      name: 'upsert_design_profile',
      arguments: {
        partner_id,
        brand_dna,
        ux_persona,
        style_preferences,
        design_constraints
      }
    }
  })
});

const result = await response.json();

return [{ json: {
  partner_id,
  upsert_result: result?.result?.content?.[0]?.text ?? JSON.stringify(result)
} }];

// Format final response
const result = $input.first().json;

return [{ json: {
  success: true,
  signal: 'design_dna_interview_complete',
  partner_id: result.partner_id,
  upsert_result: result.upsert_result
} }];
